{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, a long-chain ester prodrug with a complex polar scaffold, had only 15% oral bioavailability in humans, below the 20% threshold; this demonstrates that lipophilic ester prodrugs can be poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Chloramphenicol palmitate, a long-chain fatty acid ester prodrug, showed 85 ± 15% absolute oral bioavailability in children, indicating that such esters can be well absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C30"],
      "claim": "Valomaciclovir stearate, a long-chain fatty ester prodrug, achieved >60% oral bioavailability in humans.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "DINCH, a lipophilic diester plasticizer, was almost completely bioavailable in humans at 1 mg/kg.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Perindopril, an ester prodrug ACE inhibitor, had about 66% absolute oral bioavailability in humans.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Capecitabine, an orally administered carbamate prodrug, has near-complete oral bioavailability in humans.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a beta-lactone lipase inhibitor designed to act locally in the gastrointestinal tract; its systemic oral bioavailability is negligible and far below 20%. The one directly relevant low-F ester prodrug analogue (laninamivir octanoate, 15%) supports low, while the many high-F lipophilic esters are less transferable because they lack the non-absorbable beta-lactone/lipase-inhibitor design.",
  "evidence_gaps": [
    "No direct experimental record for orlistat itself; all provided records are structural analogues.",
    "The only low-F analogue (laninamivir octanoate) still differs in scaffold and mechanism from the beta-lactone N-formylleucine ester of orlistat.",
    "Most analogue records report total or relative bioavailability without specifying absolute F or exact conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

